const upsertUser = `-- name: UpsertUser :one
INSERT INTO users (oidc_sub, email, first_name, last_name, role, last_login)
VALUES ($1, $2, $3, $4, $5, NOW())
    ON CONFLICT (oidc_sub)
DO UPDATE SET
    email = EXCLUDED.email,
           first_name = EXCLUDED.first_name,
           last_name = EXCLUDED.last_name,
           role = EXCLUDED.role,
           last_login = NOW()
           RETURNING id, email, first_name, last_name, oidc_sub, password_hash, email_verified, role, created_at, last_login
`

type UpsertUserParams struct {
	OidcSub   string
	Email     string
	FirstName string
	LastName  string
	Role      UserRole
}

func (q *Queries) UpsertUser(ctx context.Context, arg UpsertUserParams) (User, error) {
	row := q.db.QueryRowContext(ctx, upsertUser,
		arg.OidcSub,
		arg.Email,
		arg.FirstName,
		arg.LastName,
		arg.Role,
	)
	var i User
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.FirstName,
		&i.LastName,
		&i.OidcSub,
		&i.PasswordHash,
		&i.EmailVerified,
		&i.Role,
		&i.CreatedAt,
		&i.LastLogin,
	)
	return i, err
}
